package net.minecraft.server.level;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.resources.*;import net.minecraft.server.*;import net.minecraft.world.level.block.entity.*;import java.util.*;public class ServerLevel {private final MinecraftServer server;public ServerLevel(MinecraftServer s){server=s;}public long day;public long getGameTime(){return day;}public net.minecraft.world.level.block.state.BlockState getBlockState(BlockPos p){return new net.minecraft.world.level.block.state.BlockState();}public net.minecraft.world.item.crafting.RecipeManager getRecipeManager(){return new net.minecraft.world.item.crafting.RecipeManager();}public Object registryAccess(){return new Object();}public long getDayTime(){return day;}public MinecraftServer getServer(){return server;}public MinecraftServer.DataStore getDataStorage(){return server.store;}public Dim dimension(){return new Dim();}public class Dim {public ResourceLocation location(){return new ResourceLocation("overworld");}}public final Map<BlockPos,BlockEntity> entities=new HashMap<>();public boolean hasChunkAt(BlockPos pos){return true;}public BlockEntity getBlockEntity(BlockPos pos){return entities.get(pos);}public final Map<java.util.UUID,Object> people=new HashMap<>();public Object getEntity(java.util.UUID id){return people.get(id);}}